import pyomo.environ as pyo

DATA = {
    "foods": ["chicken", "tofu", "spinach", "beef", "eggs", "rice", "bananas", "quinoa"],
    "nutrients": ["protein", "carbs", "calories"],
    # cost per serving
    "cost": {
        "chicken": 7, "tofu": 7, "spinach": 1, "beef": 9,
        "eggs": 6, "rice": 7, "bananas": 2, "quinoa": 6,
    },
    # nutrient content per serving
    "protein": {
        "chicken": 12, "tofu": 10, "spinach": 11, "beef": 8,
        "eggs": 16, "rice": 4, "bananas": 4, "quinoa": 4,
    },
    "carbs": {
        "chicken": 5, "tofu": 1, "spinach": 30, "beef": 26,
        "eggs": 9, "rice": 25, "bananas": 16, "quinoa": 20,
    },
    "calories": {
        "chicken": 231, "tofu": 210, "spinach": 295, "beef": 211,
        "eggs": 232, "rice": 146, "bananas": 255, "quinoa": 205,
    },
    # daily requirements (minimums)
    "requirement": {"protein": 91, "carbs": 136, "calories": 1563},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.F = pyo.Set(initialize=d["foods"])
    model.N = pyo.Set(initialize=d["nutrients"])

    # Decision variables: servings of each food
    model.x = pyo.Var(model.F, within=pyo.NonNegativeReals, bounds=(0, None))

    # Objective: minimise total cost
    model.obj = pyo.Objective(
        expr=sum(d["cost"][i] * model.x[i] for i in model.F),
        sense=pyo.minimize,
    )

    # Nutrient-requirement constraint mapping nutrient -> content lookup
    content = {n: d[n] for n in d["nutrients"]}

    def nutrient_rule(m, n):
        return sum(content[n][i] * m.x[i] for i in m.F) >= d["requirement"][n]

    model.nutrient_req = pyo.Constraint(model.N, rule=nutrient_rule)

    return model


